/* @settings
name: Cosmic
id: cosmic-theme-settings
settings:
  - id: cosmic-info
    title: Welcome to Cosmic
    type: info-text
    markdown: false

  - id: cosmic-color-heading
    title: Colors and Moods
    type: heading
    level: 1
    collapsed: false

  - id: cosmic-color-scheme
    title: Color Scheme
    description: Pick the version of Cosmic you feel like using today. Every choice includes its own light and dark colors.
    type: class-select
    allowEmpty: false
    default: cosmic-scheme-original
    options:
      - label: Cosmic (original)
        value: cosmic-scheme-original
      - label: Red Dwarf
        value: cosmic-scheme-red-dwarf
      - label: Blue Blob
        value: cosmic-scheme-blue-blob
      - label: Aurora
        value: cosmic-scheme-aurora
      - label: Eclipse
        value: cosmic-scheme-eclipse
      - label: Stardust
        value: cosmic-scheme-stardust
      - label: Comet
        value: cosmic-scheme-comet

  - id: cosmic-custom-color-heading
    title: Change Individual Colors
    type: heading
    level: 2
    collapsed: true

  - id: cosmic-accent
    title: Main Accent Color
    description: The primary highlight used for active items, links, buttons, borders, and decorative details.
    type: variable-color
    default: "#b4797f"
    format: hex

  - id: cosmic-accent-hover
    title: Accent Color on Hover
    description: The brighter accent you see when the pointer moves over an interactive item.
    type: variable-color
    default: "#c57e89"
    format: hex

  - id: cosmic-h1-color
    title: Largest Heading Color (H1)
    description: The color used for the biggest heading in a note.
    type: variable-color
    default: "#dda2a1"
    format: hex

  - id: cosmic-h2-color
    title: Large Heading Color (H2)
    description: The color used for second-level headings.
    type: variable-color
    default: "#97c7dc"
    format: hex

  - id: cosmic-h3-color
    title: Medium Heading Color (H3)
    description: The color used for third-level headings and several smaller accents.
    type: variable-color
    default: "#d8c2e3"
    format: hex

  - id: cosmic-typography-heading
    title: Fonts and Headings
    type: heading
    level: 1
    collapsed: false

  - id: font-text-theme
    title: Note Font
    description: The main font used for paragraphs, lists, and everyday writing.
    type: variable-select
    default: Tirra
    options:
      - Tirra
      - Source Serif 4
      - Georgia

  - id: font-display
    title: Heading Font
    description: The font used for note titles and prominent headings.
    type: variable-select
    default: Yeseva One
    options:
      - Yeseva One
      - Cormorant Garamond
      - Georgia

  - id: cosmic-layout-heading
    title: Size and Spacing
    type: heading
    level: 1
    collapsed: false

  - id: file-line-width
    title: Note Text Width
    description: Sets the maximum width of your writing area in Reading View and the editor.
    type: variable-number-slider
    default: 760
    min: 520
    max: 1100
    step: 10
    format: px

  - id: cosmic-density
    title: Interface Spacing
    description: Cozy is the balanced default. Compact fits more on screen, while Airy adds breathing room.
    type: class-select
    allowEmpty: false
    default: cosmic-density-cozy
    options:
      - label: Cozy
        value: cosmic-density-cozy
      - label: Compact
        value: cosmic-density-compact
      - label: Airy
        value: cosmic-density-airy

  - id: cosmic-surfaces-heading
    title: Backgrounds and Surfaces
    type: heading
    level: 1
    collapsed: false

  - id: cosmic-sidebar-contrast
    title: Sidebar Background
    description: Muted blends into the workspace, Separated is easier to distinguish, and Deep makes dark-mode sidebars darker.
    type: class-select
    allowEmpty: false
    default: cosmic-sidebar-muted
    options:
      - label: Muted
        value: cosmic-sidebar-muted
      - label: Separated
        value: cosmic-sidebar-separated
      - label: Deep (Dark Mode Only)
        value: cosmic-sidebar-deep

  - id: cosmic-atmosphere
    title: Workspace Background
    description: Flat is completely plain. Nebula adds a visible palette-colored glow. Deep Space is darker and more dramatic, with stronger color, a vignette, and scattered stars.
    type: class-select
    allowEmpty: false
    default: cosmic-atmosphere-nebula
    options:
      - label: Flat
        value: cosmic-atmosphere-flat
      - label: Nebula
        value: cosmic-atmosphere-nebula
      - label: Deep Space
        value: cosmic-atmosphere-deep

  - id: cosmic-extras-heading
    title: Finishing Touches
    type: heading
    level: 1
    collapsed: true

  - id: cosmic-callouts
    title: Callout Style
    description: Choose whether callouts look softly tinted, more solid, or outlined with a clear interior.
    type: class-select
    allowEmpty: false
    default: cosmic-callouts-soft
    options:
      - label: Soft
        value: cosmic-callouts-soft
      - label: Solid
        value: cosmic-callouts-solid
      - label: Outlined
        value: cosmic-callouts-outlined

  - id: cosmic-statusbar
    title: Status Bar Style
    description: Default keeps the full bar, Pill makes it float, and Minimal removes its background.
    type: class-select
    allowEmpty: false
    default: cosmic-statusbar-default
    options:
      - label: Default
        value: cosmic-statusbar-default
      - label: Pill
        value: cosmic-statusbar-pill
      - label: Minimal
        value: cosmic-statusbar-minimal

  - id: cosmic-plain-embeds
    title: Remove Frames from Embeds
    description: Turn this on when you want embedded notes and files to blend into the page without Cosmic borders or card styling.
    type: class-toggle
    default: false

  - id: cosmic-reduce-effects
    title: Turn Off Decorative Effects
    description: Removes ambient glow, decorative shadows, and transitions. Useful for a calmer look or better performance.
    type: class-toggle
    default: false
*/

