/* base color palette */

body {
  /* Deep space */
  --void: #010107;
  --black: #020412;
  --abyss: #03071d;
  --ink: #201b43;

  /* Ocean */
  --cove: #051c36;
  --marine: #07294d;
  --blue: #30506f;

  /* Purple */
  --plum: #291236;
  --grape: #351e4d;
  --violet: #3a2e5f;
  --iris: #412a65;
  --orchid: #593670;
  --amethyst: #714271;
  --lavender: #b8a5cc;
  --lilac: #d8c2e3;

  /* Rose */
  --wine: #411e42;
  --berry: #5f314f;
  --mulberry: #7e4265;
  --mauve: #8b526c;
  --rose: #b4797f;
  --blush: #d29596;
  --petal: #dda2a1;

  /* Pale surfaces */
  --shell: #ead6d7;
  --pearl: #f4ebec;
  --cloud: #ecedf4;
  --cream: #f2def2;
  --peach: #f3cade;

  /* Decorative lights */
  --ochre: #975ab5;
  --gold: #e0b2e8;
  --glint: #f3d8f6;

  /* Special-purpose colors */
  --sky: #97c7dc;
  --mist: #8e8392;
  --smoke: #724d71;
  --ember: #c57e89;

  /* Default semantic colors */
  --cosmic-accent: var(--rose);
  --cosmic-accent-hover: var(--ember);

  --cosmic-h1-color: var(--petal);
  --cosmic-h2-color: var(--sky);
  --cosmic-h3-color: var(--lilac);

  /* Material defaults */
  --cosmic-note-surface-opacity: 100%;
  --cosmic-transition-duration: 160ms;

  /* Default typography */
  --font-interface-theme: "Inter", "Avenir Next", "IBM Plex Sans", sans-serif;
  --font-text-theme: "Tirra", "Source Serif 4", Georgia, serif;
  --font-monospace-theme:
    "IBM Plex Mono", "SFMono-Regular", Menlo, Consolas, monospace;

  --font-interface: var(--font-interface-override), var(--font-interface-theme);
  --font-text: var(--font-text-override), var(--font-text-theme);
  --font-monospace: var(--font-monospace-override), var(--font-monospace-theme);
  --font-editor-theme: var(--font-text-theme);

  --h1-font: var(--font-display);
  --h2-font: var(--font-display);
  --h3-font: var(--font-text-theme);
  --h5-font: var(--font-interface-theme);
  --h4-font: var(--font-interface-theme);
  --h6-font: var(--font-interface-theme);

  --h1-style: italic;
  --h2-style: italic;
  --h3-style: italic;
  --h4-style: italic;
  --h1-weight: 400;
  --h2-weight: 400;
  --h6-weight: 700;
  --h5-size: 0.92em;
  --h5-transform: uppercase;
  --h6-transform: uppercase;
}

/* Shared light and dark semantic mappings */

.theme-dark,
.theme-light {
  --background-secondary: var(--background-primary);
  --background-secondary-alt: var(--background-primary-alt);

  --interactive-accent: var(--cosmic-accent);
  --interactive-accent-hover: var(--cosmic-accent-hover);

  --h1-color: var(--cosmic-h1-color);
  --h2-color: var(--cosmic-h2-color);
  --h3-color: var(--cosmic-h3-color);

  --cosmic-control-background: color-mix(
    in srgb,
    var(--background-primary-alt) 84%,
    var(--cosmic-accent)
  );
  --cosmic-control-hover: color-mix(
    in srgb,
    var(--background-primary-alt) 70%,
    var(--cosmic-accent)
  );
  --cosmic-control-border: color-mix(
    in srgb,
    var(--cosmic-accent) 34%,
    var(--background-modifier-border)
  );

  --background-modifier-hover: color-mix(
    in srgb,
    var(--cosmic-accent) 16%,
    transparent
  );
  --background-modifier-active-hover: color-mix(
    in srgb,
    var(--cosmic-accent) 24%,
    transparent
  );
  --background-modifier-border: color-mix(
    in srgb,
    var(--text-muted) 24%,
    transparent
  );
  --background-modifier-border-hover: color-mix(
    in srgb,
    var(--cosmic-accent) 40%,
    transparent
  );
  --background-modifier-border-focus: var(--cosmic-accent);
  --background-modifier-error: var(--cosmic-h1-color);
  --background-modifier-error-hover: var(--cosmic-accent-hover);
  --background-modifier-success: var(--h5-color);
  --background-modifier-form-field: color-mix(
    in srgb,
    var(--background-primary-alt) 94%,
    var(--text-normal)
  );

  --text-on-accent: var(--background-primary);
  --text-selection: color-mix(in srgb, var(--cosmic-accent) 28%, transparent);
  --text-highlight-bg: color-mix(
    in srgb,
    var(--cosmic-h3-color) 30%,
    transparent
  );
  --highlight-background: var(--text-highlight-bg);
  --highlight-background-red: color-mix(
    in srgb,
    var(--cosmic-h1-color) 36%,
    transparent
  );
  --highlight-background-orange: color-mix(
    in srgb,
    var(--h6-color) 38%,
    transparent
  );
  --highlight-background-yellow: color-mix(
    in srgb,
    var(--text-accent) 34%,
    transparent
  );
  --highlight-background-green: color-mix(
    in srgb,
    var(--h5-color) 34%,
    transparent
  );
  --highlight-background-blue: color-mix(
    in srgb,
    var(--cosmic-h2-color) 36%,
    transparent
  );
  --highlight-background-purple: color-mix(
    in srgb,
    var(--cosmic-h3-color) 38%,
    transparent
  );
  --text-error: var(--cosmic-h1-color);
  --text-success: var(--h5-color);
  --caret-color: var(--cosmic-accent-hover);
  --active-line-bg: color-mix(
    in srgb,
    var(--cosmic-accent) 8%,
    transparent
  );

  --interactive-normal: color-mix(
    in srgb,
    var(--background-primary-alt) 88%,
    var(--cosmic-accent)
  );
  --interactive-hover: color-mix(
    in srgb,
