:root {
  --font-display: "Yeseva One", "Cormorant Garamond", Georgia, serif;

  --radius-s: 5px;
  --radius-m: 7px;
  --radius-l: 10px;
  --input-radius: 6px;
  --tab-radius-active: 6px 6px 0 0;
  --checkbox-radius: 4px;
  --modal-radius: 10px;

  --divider-width: 1px;
  --bold-weight: 800;
}

/* Workspace atmosphere */

.workspace {
  position: relative;
  isolation: isolate;
  background-color: var(--background-primary);
}

.workspace::before {
  content: "";
  position: absolute;
  z-index: 0;
  inset: 0;
  background: none;
  pointer-events: none;
}

.horizontal-main-container,
.workspace-split,
.workspace-tabs,
.workspace-leaf,
.workspace-leaf-content {
  background-color: transparent;
}

.horizontal-main-container,
.workspace-split.mod-root {
  position: relative;
  z-index: 1;
  background-color: transparent !important;
}

body.cosmic-atmosphere-flat {
  --cosmic-pane-glow-dark: 0%;
  --cosmic-pane-highlight-dark: 0%;
  --cosmic-pane-glow-light: 0%;
  --cosmic-pane-highlight-light: 0%;
  --cosmic-pane-edge-strength: 4%;
  --cosmic-atmosphere-note-opacity: 100%;
}

body.cosmic-atmosphere-nebula {
  --cosmic-pane-glow-dark: 11%;
  --cosmic-pane-highlight-dark: 10%;
  --cosmic-pane-glow-light: 16%;
  --cosmic-pane-highlight-light: 24%;
  --cosmic-pane-edge-strength: 10%;
  --cosmic-atmosphere-note-opacity: 95%;
}

body.cosmic-atmosphere-nebula .workspace::before {
  background:
    radial-gradient(
      circle at 10% 5%,
      color-mix(in srgb, var(--cosmic-accent) 42%, transparent),
      transparent 48rem
    ),
    radial-gradient(
      circle at 90% 16%,
      color-mix(in srgb, var(--cosmic-h2-color) 34%, transparent),
      transparent 40rem
    ),
    radial-gradient(
      circle at 54% 96%,
      color-mix(in srgb, var(--cosmic-h3-color) 28%, transparent),
      transparent 44rem
    ),
    linear-gradient(
      145deg,
      color-mix(in srgb, var(--background-primary) 76%, transparent),
      color-mix(in srgb, var(--background-primary-alt) 86%, transparent)
    );
  background-blend-mode: screen, screen, normal, normal;
}

body.cosmic-atmosphere-deep {
  --cosmic-pane-glow-dark: 5%;
  --cosmic-pane-highlight-dark: 4%;
  --cosmic-pane-glow-light: 8%;
  --cosmic-pane-highlight-light: 7%;
  --cosmic-pane-edge-strength: 18%;
  --cosmic-atmosphere-note-opacity: 88%;
  --cosmic-deep-base-start: var(--background-primary);
  --cosmic-deep-base-end: var(--background-primary-alt);
}

body.cosmic-atmosphere-deep.theme-dark {
  --cosmic-deep-base-start: color-mix(
    in srgb,
    var(--background-primary) 82%,
    black
  );
  --cosmic-deep-base-end: color-mix(
    in srgb,
    var(--background-primary-alt) 76%,
    black
  );
}

body.cosmic-atmosphere-deep .workspace::before {
  background:
    radial-gradient(
      circle at 8% 13%,
      color-mix(in srgb, var(--text-normal) 94%, transparent) 0 1.35px,
      transparent 2px
    ),
    radial-gradient(
      circle at 27% 7%,
      color-mix(in srgb, var(--cosmic-h2-color) 96%, transparent) 0 1.2px,
      transparent 1.9px
    ),
    radial-gradient(
      circle at 73% 19%,
      color-mix(in srgb, var(--text-normal) 90%, transparent) 0 1.5px,
      transparent 2.2px
    ),
    radial-gradient(
      circle at 91% 42%,
      color-mix(in srgb, var(--cosmic-h3-color) 94%, transparent) 0 1.25px,
      transparent 2px
    ),
    radial-gradient(
      circle at 61% 78%,
      color-mix(in srgb, var(--text-normal) 88%, transparent) 0 1.35px,
      transparent 2px
    ),
    radial-gradient(
      circle at 18% 84%,
      color-mix(in srgb, var(--cosmic-accent) 96%, transparent) 0 1.5px,
      transparent 2.2px
    ),
    radial-gradient(
      circle at 12% 4%,
      color-mix(in srgb, var(--cosmic-accent) 18%, transparent),
      transparent 58rem
    ),
    radial-gradient(
      circle at 88% 12%,
      color-mix(in srgb, var(--cosmic-h2-color) 16%, transparent),
      transparent 46rem
    ),
    radial-gradient(
      circle at 52% 100%,
      color-mix(in srgb, var(--cosmic-h3-color) 14%, transparent),
      transparent 50rem
    ),
    radial-gradient(
      ellipse at center,
      transparent 28%,
      color-mix(in srgb, var(--background-primary-alt) 76%, transparent) 100%
    ),
    linear-gradient(
      145deg,
      var(--cosmic-deep-base-start),
      var(--cosmic-deep-base-end)
    );
  background-blend-mode:
    screen, screen, screen, screen, screen, screen, screen, screen, screen,
    multiply, normal;
}

/* Note surfaces */

.workspace-leaf-content[data-type="markdown"] .view-content {
  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--cosmic-accent) var(--cosmic-pane-glow-current),
        transparent
      ),
      transparent 34rem
    ),
    radial-gradient(
      circle at 92% 8%,
      color-mix(
        in srgb,
        var(--cosmic-h1-color) var(--cosmic-pane-highlight-current),
        transparent
      ),
      transparent 18rem
    ),
    color-mix(
      in srgb,
      var(--background-primary)
        var(
          --cosmic-atmosphere-note-opacity,
          var(--cosmic-note-surface-opacity)
        ),
      transparent
    );
  border-inline: var(
    --cosmic-pane-inline-border,
    1px solid color-mix(in srgb, var(--cosmic-accent) 12%, transparent)
  );
}

.theme-dark .workspace-leaf-content[data-type="markdown"] .view-content {
  box-shadow:
    inset 1px 0 0
      color-mix(
        in srgb,
        var(--cosmic-accent) var(--cosmic-pane-edge-strength, 10%),
        transparent
      ),
    inset -1px 0 0
      color-mix(in srgb, var(--background-primary-alt) 30%, transparent);
}

/* Headings */

.markdown-rendered h1,
.markdown-source-view.mod-cm6 .cm-header-1 {
  letter-spacing: 0.01em;
}

.markdown-rendered h2,
.markdown-source-view.mod-cm6 .cm-header-2 {
  letter-spacing: 0.02em;
}

.markdown-rendered h5,
.markdown-source-view.mod-cm6 .cm-header-5 {
  letter-spacing: 0.08em;
}

.markdown-rendered h4,
.markdown-source-view.mod-cm6 .cm-header-4 {
  letter-spacing: 0.04em;
}

.markdown-rendered h6,
.markdown-source-view.mod-cm6 .cm-header-6 {
  letter-spacing: 0.12em;
  opacity: 0.9;
}

/* Emphasis */

.markdown-rendered strong,
.cm-strong {
  color: color-mix(in srgb, var(--cosmic-h2-color) 78%, var(--cosmic-accent));
  font-weight: var(--bold-weight);
}

.theme-light .markdown-rendered strong,
.theme-light .cm-strong {
  color: var(--text-normal);
}

.markdown-rendered em,
.cm-em {
  color: var(--h4-color);
  font-family: var(--font-text-theme);
}

.markdown-rendered blockquote,
.HyperMD-quote {
  border-inline-start-width: 3px;
  border-start-start-radius: 0;
  border-start-end-radius: var(--radius-m);
  border-end-end-radius: var(--radius-m);
  border-end-start-radius: 0;
  background: color-mix(in srgb, var(--interactive-accent) 8%, transparent);
}

.markdown-rendered mark,
.cm-s-obsidian span.cm-formatting-highlight,
.cm-s-obsidian span.cm-highlight {
  color: inherit;
  padding: 0 0.12em;
  border-radius: 3px;
}

/* Obsidian 1.14 colored highlights */

.cm-s-obsidian span.cm-highlight-red {
  --highlight-background: var(--highlight-background-red);
}

.cm-s-obsidian span.cm-highlight-orange {
  --highlight-background: var(--highlight-background-orange);
}

.cm-s-obsidian span.cm-highlight-yellow {
  --highlight-background: var(--highlight-background-yellow);
}

.cm-s-obsidian span.cm-highlight-green {
  --highlight-background: var(--highlight-background-green);
}

.cm-s-obsidian span.cm-highlight-blue {
  --highlight-background: var(--highlight-background-blue);
}

.cm-s-obsidian span.cm-highlight-purple {
  --highlight-background: var(--highlight-background-purple);
}

/* Editor focus and raw frontmatter */

.markdown-source-view.mod-cm6 .cm-content,
.markdown-source-view.mod-cm6 .cm-line {
  caret-color: var(--caret-color);
}

.markdown-source-view.mod-cm6 .cm-active.cm-line,
.markdown-source-view.mod-cm6 .cm-activeLine {
  background-color: var(--active-line-bg);
}

.markdown-source-view.mod-cm6 .cm-activeLineGutter {
  color: var(--cosmic-accent-hover);
  background-color: var(--active-line-bg);
}

.markdown-source-view.mod-cm6
  :is(.HyperMD-frontmatter, .cm-hmd-frontmatter) {
  color: var(--text-muted);
  background-color: color-mix(
    in srgb,
    var(--background-primary-alt) 72%,
    transparent
  );
}

.markdown-source-view.mod-cm6
  :is(.HyperMD-frontmatter, .cm-hmd-frontmatter)
  :is(.cm-atom, .cm-meta) {
  color: var(--cosmic-accent);
}

/* Inline code */

.markdown-rendered code,
.cm-inline-code {
  padding: 0.1em 0.28em;
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
}

.markdown-rendered code,
.cm-inline-code,
.cm-s-obsidian .HyperMD-codeblock {
  font-weight: 700;
}

.theme-dark .markdown-rendered :not(pre) > code,
.theme-dark .cm-inline-code {
  color: var(--cosmic-h1-color) !important;
  border-color: color-mix(in srgb, var(--cosmic-accent) 52%, var(--h4-color));
  background-color: color-mix(in srgb, var(--cosmic-accent) 32%, transparent);
}

/* Code blocks */

.cm-s-obsidian div.HyperMD-codeblock-begin {
  border-radius: var(--radius-m) var(--radius-m) 0 0;
}

.cm-s-obsidian div.HyperMD-codeblock-bg {
  border-radius: 0;
}

.cm-s-obsidian div.HyperMD-codeblock-end {
  border-radius: 0 0 var(--radius-m) var(--radius-m);
}

.markdown-rendered pre {
  position: relative;
  padding: 1.15rem 1.25rem;
  border: 1px solid var(--background-modifier-border);
  background: var(--code-background);
  box-shadow: 0 3px 10px
    color-mix(in srgb, var(--background-primary-alt) 18%, transparent);
  border-radius: var(--radius-m);
}

.markdown-rendered pre button.copy-code-button {
  inset-block-start: 0.55rem;
  inset-inline-end: 0.55rem;
  padding: 0.25rem 0.55rem;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  color: var(--text-muted);
  background-color: var(--background-primary-alt);
}

.markdown-rendered pre button.copy-code-button:hover {
  color: var(--text-normal);
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 48%,
    var(--background-modifier-border)
  );
}

.markdown-source-view.mod-cm6 .HyperMD-codeblock-begin {
  padding-top: 0.55rem;
}

.markdown-source-view.mod-cm6 .HyperMD-codeblock-end {
  padding-bottom: 0.55rem;
}

/* Bright syntax colors in Live Preview and Reading View */

.cm-s-obsidian .HyperMD-codeblock :is(.cm-keyword, .cm-qualifier),
.markdown-rendered pre :is(.token.keyword, .token.atrule) {
  color: var(--code-keyword);
}

.cm-s-obsidian
  .HyperMD-codeblock
  :is(.cm-def, .cm-variable-2, .cm-builtin, .cm-type),
.markdown-rendered pre :is(.token.function, .token.class-name, .token.builtin) {
  color: var(--code-function);
}

.cm-s-obsidian
  .HyperMD-codeblock
  :is(.cm-variable, .cm-property, .cm-attribute),
.markdown-rendered pre :is(.token.property, .token.attr-name, .token.variable) {
  color: var(--code-property);
}

.cm-s-obsidian .HyperMD-codeblock :is(.cm-string, .cm-string-2),
.markdown-rendered
  pre
  :is(.token.string, .token.char, .token.attr-value, .token.regex) {
  color: var(--code-string);
}

.cm-s-obsidian .HyperMD-codeblock :is(.cm-number, .cm-atom),
.markdown-rendered
  pre
  :is(.token.number, .token.boolean, .token.constant, .token.symbol) {
  color: var(--code-value);
}

.cm-s-obsidian .HyperMD-codeblock .cm-operator,
.markdown-rendered pre :is(.token.operator, .token.entity, .token.url) {
  color: var(--code-operator);
}

.cm-s-obsidian .HyperMD-codeblock :is(.cm-tag, .cm-bracket),
.markdown-rendered pre :is(.token.tag, .token.selector) {
  color: var(--code-tag);
}

.cm-s-obsidian .HyperMD-codeblock :is(.cm-comment, .cm-meta),
.markdown-rendered
  pre
  :is(.token.comment, .token.prolog, .token.doctype, .token.cdata) {
  color: var(--code-comment);
  font-style: italic;
}

.cm-s-obsidian .HyperMD-codeblock :is(.cm-error, .cm-strong),
.markdown-rendered pre :is(.token.important, .token.bold) {
  color: var(--code-important);
  font-weight: 700;
}

.markdown-rendered pre .token.punctuation,
.cm-s-obsidian .HyperMD-codeblock .cm-punctuation {
  color: var(--code-punctuation);
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-code-nowrap pre,
.cosmic-code-nowrap :is(.markdown-preview-view, .markdown-rendered) pre,
.markdown-source-view.mod-cm6.cosmic-code-nowrap .HyperMD-codeblock {
  white-space: pre;
  overflow-x: auto;
}

.markdown-source-view.mod-cm6.cosmic-code-lines .cm-scroller,
.cosmic-code-lines .markdown-source-view.mod-cm6 .cm-scroller {
  counter-reset: cosmic-code-line;
}

.markdown-source-view.mod-cm6.cosmic-code-lines .HyperMD-codeblock-begin,
.cosmic-code-lines .markdown-source-view.mod-cm6 .HyperMD-codeblock-begin {
  counter-reset: cosmic-code-line;
}

.markdown-source-view.mod-cm6.cosmic-code-lines
  .HyperMD-codeblock:not(.HyperMD-codeblock-begin, .HyperMD-codeblock-end),
.cosmic-code-lines
  .markdown-source-view.mod-cm6
  .HyperMD-codeblock:not(.HyperMD-codeblock-begin, .HyperMD-codeblock-end) {
  counter-increment: cosmic-code-line;
}

.markdown-source-view.mod-cm6.cosmic-code-lines
  .HyperMD-codeblock:not(
    .HyperMD-codeblock-begin,
    .HyperMD-codeblock-end
  )::before,
.cosmic-code-lines
  .markdown-source-view.mod-cm6
  .HyperMD-codeblock:not(
    .HyperMD-codeblock-begin,
    .HyperMD-codeblock-end
  )::before {
  content: counter(cosmic-code-line);
  display: inline-block;
  width: 2.4rem;
  margin-inline-end: 0.8rem;
  color: var(--text-faint);
  text-align: end;
  font-variant-numeric: tabular-nums;
}

.markdown-source-view.mod-cm6.cosmic-code-compact .HyperMD-codeblock,
.cosmic-code-compact .markdown-source-view.mod-cm6 .HyperMD-codeblock,
:is(.markdown-preview-view, .markdown-rendered).cosmic-code-compact pre,
.cosmic-code-compact :is(.markdown-preview-view, .markdown-rendered) pre {
  line-height: 1.35;
}

/* Footnotes */

.markdown-rendered .footnotes {
  margin-block-start: 2.5rem;
  padding-block-start: 1rem;
  border-block-start: 1px solid var(--background-modifier-border);
  color: var(--text-muted);
  font-size: var(--font-smallest);
}

.markdown-rendered :is(.footnote-ref, .footnote-backref) {
  color: var(--cosmic-accent);
  font-family: var(--font-interface);
  font-weight: 700;
  text-decoration: none;
}

.markdown-rendered .footnote-ref {
  padding-inline: 0.12em;
  border-radius: 3px;
  background-color: color-mix(
    in srgb,
    var(--cosmic-accent) 12%,
    transparent
  );
}

/* Tables */

.markdown-rendered table {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--table-border-color);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--radius-m);
  box-shadow: 0 10px 28px
    color-mix(in srgb, var(--background-primary-alt) 18%, transparent);
}

.markdown-rendered th {
  color: var(--text-normal);
  font-family: var(--font-display);
  letter-spacing: 0.015em;
  background: var(--table-header-background);
}

.markdown-rendered :is(th, td) {
  padding: 0.65rem 0.8rem;
  border-color: var(--table-border-color);
}

.markdown-rendered tbody tr {
  transition: background-color var(--cosmic-transition-duration) ease;
}

.markdown-rendered tbody tr:nth-child(even) {
  background-color: var(--table-row-alt-background);
}

.markdown-rendered tbody tr:hover {
  background-color: color-mix(in srgb, var(--cosmic-accent) 10%, transparent);
}

.markdown-rendered td:is([data-type="number"], .mod-number),
.bases-table-cell[data-type="number"] {
  font-variant-numeric: tabular-nums;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-compact
  :is(th, td),
.cosmic-table-compact
  :is(.markdown-preview-view, .markdown-rendered)
  :is(th, td) {
  padding: 0.35rem 0.5rem;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-center table,
.cosmic-table-center :is(.markdown-preview-view, .markdown-rendered) table {
  margin-inline: auto;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-center :is(th, td),
.cosmic-table-center
  :is(.markdown-preview-view, .markdown-rendered)
  :is(th, td) {
  text-align: center;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-nowrap table,
.cosmic-table-nowrap :is(.markdown-preview-view, .markdown-rendered) table {
  white-space: nowrap;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-striped
  tbody
  tr:nth-child(odd),
.cosmic-table-striped
  :is(.markdown-preview-view, .markdown-rendered)
  tbody
  tr:nth-child(odd) {
  background-color: transparent;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-striped
  tbody
  tr:nth-child(even),
.cosmic-table-striped
  :is(.markdown-preview-view, .markdown-rendered)
  tbody
  tr:nth-child(even) {
  background-color: color-mix(in srgb, var(--cosmic-accent) 9%, transparent);
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-numbered table,
.cosmic-table-numbered :is(.markdown-preview-view, .markdown-rendered) table {
  counter-reset: cosmic-table-row;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-numbered tbody tr,
.cosmic-table-numbered
  :is(.markdown-preview-view, .markdown-rendered)
  tbody
  tr {
  counter-increment: cosmic-table-row;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-table-numbered
  tbody
  tr
  > :first-child::before,
.cosmic-table-numbered
  :is(.markdown-preview-view, .markdown-rendered)
  tbody
  tr
  > :first-child::before {
  content: counter(cosmic-table-row) ". ";
  color: var(--cosmic-accent);
  font-weight: 700;
}

/* Sidebar */

.nav-folder-title,
.nav-file-title,
.tree-item-self {
  border-radius: var(--radius-s);
}

.nav-folder-title .nav-folder-title-content::first-letter,
.nav-file-title .nav-file-title-content::first-letter {
  color: var(--cosmic-accent);
  font-weight: 700;
}

.nav-file-title.is-active {
  box-shadow: inset 3px 0 0 var(--interactive-accent);
}

.nav-folder-title.is-active,
.nav-folder.is-collapsed > .nav-folder-title:hover {
  color: var(--text-normal);
  background-color: color-mix(in srgb, var(--cosmic-h2-color) 10%, transparent);
}

.nav-file-title.is-active,
.tree-item-self.is-clickable.is-active {
  color: var(--text-normal);
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--cosmic-accent) 16%, transparent),
      transparent
    ),
    color-mix(in srgb, var(--background-secondary-alt) 70%, transparent);
}

:is(body.mod-rtl, [dir="rtl"]) .nav-file-title.is-active {
  box-shadow: inset -3px 0 0 var(--interactive-accent);
}

:is(body.mod-rtl, [dir="rtl"])
  :is(.nav-file-title.is-active, .tree-item-self.is-clickable.is-active) {
  background:
    linear-gradient(
      -90deg,
      color-mix(in srgb, var(--cosmic-accent) 16%, transparent),
      transparent
    ),
    color-mix(in srgb, var(--background-secondary-alt) 70%, transparent);
}

.view-header-breadcrumb,
.view-header-breadcrumb-separator {
  color: var(--text-muted);
}

.view-header-breadcrumb:hover,
.view-header-breadcrumb:last-of-type {
  color: var(--cosmic-accent);
}

.search-result-file-title {
  color: var(--cosmic-accent);
  font-family: var(--font-display);
}

.search-result-file-match {
  border-radius: var(--radius-s);
  background-color: color-mix(
    in srgb,
    var(--background-primary-alt) 56%,
    transparent
  );
}

.search-result-file-match:hover {
  background-color: color-mix(in srgb, var(--cosmic-accent) 10%, transparent);
  box-shadow: inset 3px 0 0 var(--cosmic-accent);
}

:is(body.mod-rtl, [dir="rtl"]) .search-result-file-match:hover {
  box-shadow: inset -3px 0 0 var(--cosmic-accent);
}

.document-search-container {
  border-bottom: 1px solid var(--background-modifier-border);
  background-color: var(--background-primary-alt);
  box-shadow: 0 6px 18px
    color-mix(in srgb, var(--background-primary) 20%, transparent);
}

.document-search-container :is(.document-search, .document-replace) {
  gap: var(--size-4-2);
}

.document-search-container input[type="text"] {
  border-color: var(--cosmic-control-border);
  background-color: var(--cosmic-control-background);
}

.document-search-container .document-search-button {
  border-radius: var(--radius-s);
}

.is-flashing,
.search-result-file-match .search-result-file-matched-text {
  color: var(--text-normal);
  background-color: var(--text-highlight-bg);
  border-radius: 3px;
}

body.cosmic-scheme-original.theme-light
  .search-result-file-match
  .search-result-file-matched-text,
body.cosmic-scheme-original.theme-light .is-flashing {
  box-shadow: 0 0 0 1px
    color-mix(in srgb, var(--cosmic-accent) 58%, transparent);
  font-weight: 700;
}

.outline .tree-item-self,
.backlink-pane .tree-item-self,
.outgoing-link-pane .tree-item-self,
.bookmarks-container .tree-item-self {
  border-inline-start: 2px solid transparent;
}

.outline .tree-item-self:hover,
.backlink-pane .tree-item-self:hover,
.outgoing-link-pane .tree-item-self:hover,
.bookmarks-container .tree-item-self:hover {
  border-inline-start-color: color-mix(
    in srgb,
    var(--cosmic-accent) 54%,
    transparent
  );
}

.embedded-backlinks,
.backlink-pane,
.outgoing-link-pane {
  --link-color: var(--cosmic-accent);
  --link-color-hover: var(--cosmic-accent-hover);
}

.nav-folder.mod-root > .nav-folder-title {
  color: var(--h5-color);
}

/* Controls */

.suggestion-item.is-selected,
.menu-item.selected,
.menu-item:hover {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--cosmic-accent) 18%, transparent),
    color-mix(in srgb, var(--cosmic-h2-color) 8%, transparent)
  );
  box-shadow: inset 3px 0 0 var(--cosmic-accent);
}

:is(body.mod-rtl, [dir="rtl"])
  :is(.suggestion-item.is-selected, .menu-item.selected, .menu-item:hover) {
  background: linear-gradient(
    -90deg,
    color-mix(in srgb, var(--cosmic-accent) 18%, transparent),
    color-mix(in srgb, var(--cosmic-h2-color) 8%, transparent)
  );
  box-shadow: inset -3px 0 0 var(--cosmic-accent);
}

.mod-cta {
  color: var(--text-on-accent);
  border-color: color-mix(in srgb, var(--cosmic-accent) 72%, transparent);
  background: linear-gradient(
    135deg,
    var(--cosmic-accent),
    color-mix(in srgb, var(--cosmic-accent) 74%, var(--cosmic-h2-color))
  );
  box-shadow: 0 8px 22px
    color-mix(in srgb, var(--cosmic-accent) 22%, transparent);
}

.tooltip {
  color: var(--text-normal);
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary-alt);
  box-shadow: 0 4px 12px
    color-mix(in srgb, var(--background-primary) 28%, transparent);
}

.notice {
  color: var(--text-normal);
  border: 1px solid color-mix(
    in srgb,
    var(--cosmic-accent) 46%,
    var(--background-modifier-border)
  );
  border-radius: var(--radius-m);
  background: color-mix(
    in srgb,
    var(--background-primary-alt) 90%,
    var(--cosmic-accent)
  );
  box-shadow: 0 10px 28px
    color-mix(in srgb, var(--background-primary) 34%, transparent);
}

:is(kbd, .setting-hotkey) {
  color: var(--text-normal);
  border: 1px solid var(--cosmic-control-border);
  border-bottom-width: 2px;
  border-radius: var(--radius-s);
  background-color: var(--cosmic-control-background);
  box-shadow: none;
}

.mod-cta:hover {
  filter: brightness(1.08) saturate(1.08);
}

button:not(.mod-cta),
input[type="text"],
input[type="search"],
input[type="number"],
input[type="password"],
select,
textarea,
.dropdown {
  border-color: var(--cosmic-control-border);
  background-color: var(--cosmic-control-background);
  transition:
    border-color var(--cosmic-transition-duration) ease,
    background-color var(--cosmic-transition-duration) ease,
    box-shadow var(--cosmic-transition-duration) ease;
}

button:not(.mod-cta):hover,
select:hover,
.dropdown:hover {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 54%,
    var(--background-modifier-border)
  );
  background-color: var(--cosmic-control-hover);
}

:is(button, input, select, textarea, .dropdown):focus-visible {
  outline: 2px solid color-mix(in srgb, var(--cosmic-accent) 78%, white);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px
    color-mix(in srgb, var(--cosmic-accent) 16%, transparent);
}

:is(
  a,
  .clickable-icon,
  .nav-file-title,
  .nav-folder-title,
  .tree-item-self
):focus-visible {
  outline: 2px solid color-mix(in srgb, var(--cosmic-accent) 78%, white);
  outline-offset: 2px;
  border-radius: var(--radius-s);
}

input[type="checkbox"] {
  border-color: var(--background-modifier-border-hover);
}

input[type="checkbox"]:checked {
  border-color: var(--interactive-accent);
  background-color: var(--interactive-accent);
}

/* Semantic task states: [/], [!], [?], [*], [>], [-], and [i] */

input[type="checkbox"][data-task]:is(
    [data-task="/"],
    [data-task="!"],
    [data-task="?"],
    [data-task="*"],
    [data-task=">"],
    [data-task="-"],
    [data-task="i"]
  ) {
  position: relative;
  border-color: color-mix(
    in srgb,
    var(--cosmic-task-color, var(--cosmic-accent)) 72%,
    var(--text-normal)
  );
  background: color-mix(
    in srgb,
    var(--cosmic-task-color, var(--cosmic-accent)) 18%,
    var(--background-primary)
  );
  box-shadow: inset 0 0 0 1px
    color-mix(
      in srgb,
      var(--cosmic-task-color, var(--cosmic-accent)) 30%,
      transparent
    );
}

input[type="checkbox"][data-task]:is(
    [data-task="/"],
    [data-task="!"],
    [data-task="?"],
    [data-task="*"],
    [data-task=">"],
    [data-task="-"],
    [data-task="i"]
  )::after {
  content: var(--cosmic-task-symbol);
  position: absolute;
  inset: 50% auto auto 50%;
  display: block;
  width: auto;
  height: auto;
  color: color-mix(
    in srgb,
    var(--cosmic-task-color, var(--cosmic-accent)) 68%,
    var(--text-normal)
  );
  background: none;
  -webkit-mask-image: none;
  mask-image: none;
  font-family: var(--font-monospace);
  font-size: 1.2em;
  font-weight: 800;
  line-height: 1;
  transform: translate(-50%, -50%);
}

input[type="checkbox"][data-task="/"] {
  --cosmic-task-symbol: "/";
  --cosmic-task-color: var(--cosmic-accent);
}

input[type="checkbox"][data-task="!"] {
  --cosmic-task-symbol: "!";
  --cosmic-task-color: var(--cosmic-h1-color);
}

input[type="checkbox"][data-task="?"] {
  --cosmic-task-symbol: "?";
  --cosmic-task-color: var(--cosmic-h3-color);
}

input[type="checkbox"][data-task="*"] {
  --cosmic-task-symbol: "★";
  --cosmic-task-color: var(--h5-color);
}

input[type="checkbox"][data-task][data-task="*"]::after {
  inset: 0;
  display: grid;
  width: auto;
  height: auto;
  place-items: center;
  transform: translateY(-2px);
}

input[type="checkbox"][data-task=">"] {
  --cosmic-task-symbol: "→";
  --cosmic-task-color: var(--cosmic-h2-color);
}

input[type="checkbox"][data-task="-"] {
  --cosmic-task-symbol: "−";
  --cosmic-task-color: var(--text-faint);
}

input[type="checkbox"][data-task="i"] {
  --cosmic-task-symbol: "i";
  --cosmic-task-color: var(--h4-color);
}

input[type="checkbox"][data-task]:is(
    [data-task="/"],
    [data-task="!"],
    [data-task="?"],
    [data-task=">"]
  )::after {
  transform: translate(-50%, calc(-50% - 1px));
}

input[type="checkbox"][data-task][data-task="/"]::after {
  inset: 0;
  display: grid;
  width: auto;
  height: auto;
  place-items: center;
  font-size: 1.1em;
  transform: translateY(-1px);
}

input[type="checkbox"][data-task][data-task=">"]::after {
  font-size: 1.32em;
}

.markdown-rendered li[data-task="-"] > :is(p, span),
.markdown-source-view.mod-cm6 .HyperMD-task-line[data-task="-"] {
  color: var(--text-muted);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--text-faint) 68%, transparent);
}

.markdown-rendered li[data-task="!"] > :is(p, span),
.markdown-source-view.mod-cm6 .HyperMD-task-line[data-task="!"] {
  color: color-mix(in srgb, var(--text-normal) 76%, var(--cosmic-h1-color));
  font-weight: 700;
}

.checkbox-container {
  border: 1px solid var(--cosmic-control-border);
  background-color: var(--cosmic-control-background);
}

.checkbox-container.is-enabled {
  border-color: color-mix(in srgb, var(--cosmic-accent) 70%, transparent);
  background-color: var(--cosmic-accent);
}

progress,
.setting-item-control input[type="range"] {
  accent-color: var(--cosmic-accent);
}

.status-bar {
  border-color: var(--background-modifier-border);
  background-color: var(--background-secondary);
}

/* Panels */

.menu,
.suggestion-container,
.modal,
.prompt,
.popover {
  border: 1px solid var(--background-modifier-border);
  background: var(--background-primary-alt);
  box-shadow: 0 8px 24px
    color-mix(in srgb, var(--background-primary) 30%, transparent);
}

.modal-bg {
  background-color: color-mix(
    in srgb,
    var(--background-primary) 72%,
    transparent
  );
}

.prompt-input-container,
.modal-header {
  border-color: var(--background-modifier-border);
  background-color: var(--background-primary-alt);
}

.menu-separator,
.suggestion-item.mod-complex .suggestion-note {
  border-color: var(--background-modifier-border);
}

.view-header,
.workspace-tab-header-container,
.workspace-ribbon {
  border-color: var(--background-modifier-border);
  background-color: var(--background-secondary);
}

.workspace-split.mod-left-split,
.workspace-split.mod-right-split {
  background: var(--background-secondary);
}

.workspace-tab-header {
  transition:
    color var(--cosmic-transition-duration) ease,
    background-color var(--cosmic-transition-duration) ease,
    box-shadow var(--cosmic-transition-duration) ease;
}

.workspace-tab-header.is-active {
  color: var(--tab-text-color-focused-active-current);
  background-color: color-mix(
    in srgb,
    var(--cosmic-accent) 14%,
    var(--background-secondary-alt)
  );
  box-shadow: inset 0 -2px 0 var(--cosmic-accent);
}

.workspace-tab-header.is-pinned .workspace-tab-header-inner-icon,
.workspace-tab-header[data-pinned="true"] .workspace-tab-header-inner-icon {
  color: var(--cosmic-accent);
}

.workspace-tab-header:not(.is-active):hover,
.clickable-icon:hover {
  color: var(--text-normal);
  background-color: color-mix(in srgb, var(--cosmic-accent) 12%, transparent);
}

/* Metadata */

.metadata-container {
  margin-block: 1rem 1.5rem;
  padding-block: 0.45rem 0.55rem;
  padding-inline: 1rem 0;
  border: 0;
  border-inline-start: 2px solid
    color-mix(in srgb, var(--cosmic-accent) 58%, transparent);
  border-radius: 0;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--cosmic-accent) 7%, transparent),
    transparent min(26rem, 72%)
  );
  box-shadow: none;
}

:is(body.mod-rtl, [dir="rtl"]) .metadata-container {
  background: linear-gradient(
    -90deg,
    color-mix(in srgb, var(--cosmic-accent) 7%, transparent),
    transparent min(26rem, 72%)
  );
}

.metadata-properties-heading,
.metadata-properties-title {
  min-height: 1.8rem;
  margin-bottom: 0.2rem;
  color: var(--text-muted);
  font-family: var(--font-interface);
  font-size: var(--font-ui-smaller);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.metadata-property {
  --metadata-label-text-color: color-mix(
    in srgb,
    var(--cosmic-accent) 78%,
    var(--text-normal)
  );

  min-height: 2rem;
  margin-block: 0;
  padding: 0.12rem 0.35rem;
  border: 0;
  border-bottom: 1px solid
    color-mix(in srgb, var(--background-modifier-border) 62%, transparent);
  border-start-start-radius: 3px;
  border-start-end-radius: 0;
  border-end-end-radius: 0;
  border-end-start-radius: 3px;
  transition:
    border-color var(--cosmic-transition-duration, 160ms) ease,
    background-color var(--cosmic-transition-duration, 160ms) ease;
}

.metadata-property:hover,
.metadata-property:focus-within {
  border-bottom-color: color-mix(
    in srgb,
    var(--cosmic-accent) 38%,
    var(--background-modifier-border)
  );
  background-color: color-mix(in srgb, var(--cosmic-accent) 6%, transparent);
}

.metadata-property-key {
  color: var(--metadata-label-text-color);
  background-color: transparent;
  font-family: var(--font-interface);
  font-size: var(--font-ui-small);
  font-style: normal;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.metadata-property-icon {
  color: var(--metadata-label-text-color);
}

.metadata-property-value {
  color: var(--text-normal);
}

.metadata-property-value input,
.metadata-property-value textarea {
  background-color: transparent;
}

.metadata-property .multi-select-pill {
  border: 1px solid color-mix(in srgb, var(--cosmic-accent) 18%, transparent);
  background-color: color-mix(in srgb, var(--cosmic-accent) 11%, transparent);
}

.metadata-add-button {
  margin-top: 0.25rem;
  border: 0;
  border-radius: 3px;
  color: var(--text-muted);
  background-color: transparent;
}

.metadata-add-button:hover {
  color: var(--text-normal);
  background-color: color-mix(in srgb, var(--cosmic-accent) 8%, transparent);
}

/* Per-note properties layouts */

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-compact
  .metadata-container,
.cosmic-properties-compact
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-container {
  padding: var(--size-4-2);
}

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-compact
  .metadata-property,
.cosmic-properties-compact
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-property {
  margin-block: 0;
  min-height: 1.8rem;
}

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-plain
  .metadata-container,
.cosmic-properties-plain
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-container {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-plain
  .metadata-property,
.cosmic-properties-plain
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-property {
  border-bottom: 1px solid var(--background-modifier-border);
  border-radius: 0;
}

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-card
  .metadata-properties,
.cosmic-properties-card
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-properties {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: var(--size-4-2);
}

:is(.markdown-preview-view, .markdown-source-view).cosmic-properties-card
  .metadata-property,
.cosmic-properties-card
  :is(.markdown-preview-view, .markdown-source-view)
  .metadata-property {
  padding: var(--size-4-2);
  border-color: var(--background-modifier-border);
  background-color: var(--background-primary-alt);
}

/* Callouts */

.callout {
  --callout-color: var(--interactive-accent-rgb);

  overflow: hidden;
  border: 1px solid
    color-mix(in srgb, rgb(var(--callout-color)) 28%, transparent);
  border-inline-start-width: 4px;
  border-radius: var(--radius-m);
  box-shadow: none;
}

.callout-title {
  letter-spacing: 0.015em;
}

.callout-icon {
  filter: none;
}

.callout[data-callout="note"] {
  background-color: color-mix(in srgb, var(--cosmic-h2-color) 12%, transparent);
}

.callout[data-callout="tip"],
.callout[data-callout="success"] {
  background-color: color-mix(in srgb, var(--h5-color) 13%, transparent);
}

.callout[data-callout="warning"],
.callout[data-callout="attention"] {
  background-color: color-mix(in srgb, var(--cosmic-h3-color) 14%, transparent);
}

.callout[data-callout="danger"],
.callout[data-callout="error"],
.callout[data-callout="failure"] {
  background-color: color-mix(in srgb, var(--cosmic-h1-color) 14%, transparent);
}

.callout[data-callout="quote"] {
  background-color: color-mix(in srgb, var(--text-muted) 16%, transparent);
}

.callout[data-callout="abstract"],
.callout[data-callout="summary"],
.callout[data-callout="tldr"] {
  background-color: color-mix(in srgb, var(--h4-color) 16%, transparent);
}

/* Canvas */

.canvas-node {
  border-color: var(--background-modifier-border);
  border-radius: var(--radius-m);
  background-color: var(--background-primary-alt);
  box-shadow: 0 4px 14px
    color-mix(in srgb, var(--background-primary) 24%, transparent);
}

.canvas-node.is-focused {
  border-color: var(--interactive-accent);
  box-shadow: 0 0 0 2px rgb(var(--interactive-accent-rgb), 0.24);
}

.canvas-node:nth-child(6n + 1) {
  --canvas-color: var(--cosmic-accent);
}

.canvas-node:nth-child(6n + 2) {
  --canvas-color: var(--cosmic-h2-color);
}

.canvas-node:nth-child(6n + 3) {
  --canvas-color: var(--cosmic-h3-color);
}

.canvas-node:nth-child(6n + 4) {
  --canvas-color: var(--h5-color);
}

.canvas-node:nth-child(6n + 5) {
  --canvas-color: var(--h4-color);
}

.canvas-node:nth-child(6n) {
  --canvas-color: var(--h6-color);
}

.canvas-control-group {
  border: 1px solid var(--background-modifier-border);
  background-color: var(--background-primary-alt);
  box-shadow: 0 4px 14px
    color-mix(in srgb, var(--background-primary) 24%, transparent);
}

/* Graph */

.graph-view.color-fill {
  color: var(--cosmic-accent);
}

.graph-view.color-fill-tag {
  color: var(--cosmic-h2-color);
}

.graph-view.color-fill-attachment {
  color: var(--cosmic-h3-color);
}

.graph-view.color-fill-unresolved {
  color: var(--text-faint);
}

.graph-view.color-line,
.graph-view.color-arrow {
  color: color-mix(in srgb, var(--cosmic-accent) 38%, var(--text-faint));
}

.graph-view.color-text {
  color: var(--text-normal);
}

/* Embeds */

.markdown-rendered audio {
  width: min(100%, 38rem);
}

.markdown-rendered :is(audio, video) {
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  background-color: var(--background-primary-alt);
  box-shadow: 0 6px 18px
    color-mix(in srgb, var(--background-primary-alt) 22%, transparent);
  color-scheme: dark;
}

.theme-light .markdown-rendered :is(audio, video) {
  color-scheme: light;
}

.internal-embed,
.file-embed {
  overflow: hidden;
  border: 1px solid var(--background-modifier-border);
  border-inline-start: 3px solid var(--cosmic-accent);
  border-radius: var(--radius-m);
  background: var(--background-primary-alt);
  box-shadow: none;
}

.markdown-embed-title,
.file-embed-title {
  color: var(--cosmic-accent);
  font-family: var(--font-interface-theme);
  font-weight: 650;
}

body.cosmic-plain-embeds .internal-embed,
body.cosmic-plain-embeds .file-embed {
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

/* Cosmic content components */

.callout[data-callout="constellation"] {
  --callout-color: var(--interactive-accent-rgb);
  --callout-icon: lucide-sparkles;

  background:
    radial-gradient(
      circle at 88% 18%,
      color-mix(in srgb, var(--cosmic-h2-color) 18%, transparent),
      transparent 12rem
    ),
    color-mix(in srgb, var(--cosmic-accent) 11%, transparent);
}

.callout[data-callout="orbit"] {
  --callout-color: var(--interactive-accent-rgb);
  --callout-icon: lucide-orbit;

  background:
    linear-gradient(
      115deg,
      color-mix(in srgb, var(--cosmic-h3-color) 15%, transparent),
      transparent 58%
    ),
    color-mix(in srgb, var(--h4-color) 9%, transparent);
}

.callout[data-callout="signal"] {
  --callout-color: var(--interactive-accent-rgb);
  --callout-icon: lucide-radio-tower;

  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--h5-color) 14%, transparent),
      transparent
    ),
    color-mix(in srgb, var(--cosmic-accent) 8%, transparent);
}

:is(body.mod-rtl, [dir="rtl"]) .callout[data-callout="signal"] {
  background:
    linear-gradient(
      -90deg,
      color-mix(in srgb, var(--h5-color) 14%, transparent),
      transparent
    ),
    color-mix(in srgb, var(--cosmic-accent) 8%, transparent);
}

.markdown-rendered.cosmic-card-grid,
.markdown-preview-view.cosmic-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: var(--size-4-4);
}

.cosmic-card-grid > :is(div, blockquote, .callout) {
  margin: 0;
  padding: var(--size-4-4);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-l);
  background: var(--background-primary-alt);
  box-shadow: none;
}

/* Per-note layout utilities */

:is(.markdown-preview-view, .markdown-rendered).cosmic-image-grid,
.cosmic-image-grid :is(.markdown-preview-view, .markdown-rendered) {
  container-type: inline-size;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-image-grid p:has(> img),
.cosmic-image-grid
  :is(.markdown-preview-view, .markdown-rendered)
  p:has(> img) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: var(--size-4-3);
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-image-grid p > img,
.cosmic-image-grid :is(.markdown-preview-view, .markdown-rendered) p > img {
  width: 100%;
  height: 100%;
  min-height: 10rem;
  object-fit: cover;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  box-shadow: none;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-list-cards > :is(ul, ol),
.cosmic-list-cards
  :is(.markdown-preview-view, .markdown-rendered)
  > :is(ul, ol) {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
  gap: var(--size-4-3);
  padding-inline-start: 0;
  list-style: none;
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-list-cards
  > :is(ul, ol)
  > li,
.cosmic-list-cards
  :is(.markdown-preview-view, .markdown-rendered)
  > :is(ul, ol)
  > li {
  margin: 0;
  padding: var(--size-4-4);
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  background: var(--background-primary-alt);
}

:is(.markdown-preview-view, .markdown-rendered).cosmic-wide-media
  :is(img, video, iframe, .internal-embed),
.cosmic-wide-media
  :is(.markdown-preview-view, .markdown-rendered)
  :is(img, video, iframe, .internal-embed) {
  width: min(100vw - 3rem, calc(var(--file-line-width) + 16rem));
  max-width: none;
  margin-inline: 50%;
  transform: translateX(-50%);
}

/* Bases */

.bases-view {
  --bases-table-row-background-hover: color-mix(
    in srgb,
    var(--cosmic-accent) 10%,
    transparent
  );
  --bases-cards-background: var(--background-primary-alt);
}

.bases-table-container,
.bases-cards-container {
  border-color: var(--background-modifier-border);
  border-radius: var(--radius-l);
  background: var(--background-primary-alt);
}

.bases-table-header,
.bases-table-cell {
  border-color: var(--table-border-color);
}

.bases-table-header {
  color: var(--text-normal);
  font-family: var(--font-display);
  background-color: var(--table-header-background);
}

.bases-card,
.bases-cards-item {
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  background-color: var(--background-primary-alt);
  box-shadow: none;
}

.bases-cards-item:hover {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 46%,
    var(--background-modifier-border)
  );
  box-shadow: 0 8px 24px
    color-mix(in srgb, var(--background-primary-alt) 24%, transparent);
}

.bases-group-heading {
  color: var(--text-normal);
  border-block-end: 1px solid color-mix(
    in srgb,
    var(--cosmic-accent) 24%,
    var(--background-modifier-border)
  );
}

.bases-group-heading .bases-group-property {
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.bases-group-heading .bases-group-value {
  color: var(--cosmic-accent);
  font-family: var(--font-display);
}

.is-grouped .bases-cards-container .bases-cards-group {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 20%,
    var(--background-modifier-border)
  );
}

/* PDF workspace */

.workspace-leaf-content[data-type="pdf"] .view-content,
.pdf-viewer,
.pdf-sidebar-container {
  background:
    radial-gradient(
      circle at 90% 8%,
      color-mix(in srgb, var(--cosmic-h2-color) 10%, transparent),
      transparent 18rem
    ),
    var(--background-primary);
}

.pdf-toolbar,
.pdf-container .pdf-toolbar {
  border: 1px solid var(--background-modifier-border);
  background-color: var(--background-primary-alt);
  box-shadow: 0 4px 14px
    color-mix(in srgb, var(--background-primary) 24%, transparent);
}

.pdf-viewer .page {
  overflow: hidden;
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-s);
  box-shadow: 0 14px 38px
    color-mix(in srgb, var(--background-primary-alt) 38%, transparent);
}

/* Density options */

body.cosmic-density-compact {
  --size-4-1: 0.125rem;
  --size-4-2: 0.25rem;
  --size-4-3: 0.5rem;
  --size-4-4: 0.75rem;
}

body.cosmic-density-airy {
  --size-4-1: 0.375rem;
  --size-4-2: 0.625rem;
  --size-4-3: 0.875rem;
  --size-4-4: 1.125rem;
}

/* Sidebar contrast options */

body.cosmic-sidebar-separated.theme-dark,
body.cosmic-sidebar-separated.theme-light {
  --background-secondary: color-mix(
    in srgb,
    var(--background-primary) 90%,
    var(--cosmic-accent)
  );
  --background-secondary-alt: color-mix(
    in srgb,
    var(--background-primary-alt) 92%,
    var(--cosmic-accent)
  );
}

body.cosmic-sidebar-deep.theme-dark {
  --background-secondary: color-mix(
    in srgb,
    var(--background-primary) 82%,
    var(--background-primary-alt)
  );
  --background-secondary-alt: color-mix(
    in srgb,
    var(--background-primary-alt) 88%,
    black
  );
}

/* Callout style options */

body.cosmic-callouts-solid .callout {
  border: 1px solid
    color-mix(
      in srgb,
      rgb(var(--callout-color)) 46%,
      var(--background-modifier-border)
    );
  background: color-mix(
    in srgb,
    rgb(var(--callout-color)) 27%,
    var(--background-primary)
  ) !important;
}

body.cosmic-callouts-solid.theme-light .callout {
  background: color-mix(
    in srgb,
    rgb(var(--callout-color)) 21%,
    var(--background-primary-alt)
  ) !important;
}

body.cosmic-callouts-outlined .callout {
  border: 1px solid
    color-mix(in srgb, rgb(var(--callout-color)) 56%, transparent);
  background: transparent !important;
}

/* Status bar options */

body.cosmic-statusbar-pill .status-bar {
  margin: 0.35rem;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  background-color: color-mix(
    in srgb,
    var(--background-secondary) 82%,
    transparent
  );
}

body.cosmic-statusbar-minimal .status-bar {
  border-color: transparent;
  background: transparent;
}

/* Cosmic Style Settings panel */

.style-settings-heading[data-id="cosmic-theme-settings"] {
  margin-bottom: 0;
  padding: 1rem 1.1rem 0.85rem;
  border: 1px solid var(--background-modifier-border) !important;
  border-bottom: 0 !important;
  border-radius: var(--radius-m) var(--radius-m) 0 0;
  background-color: var(--background-primary-alt);
}

.style-settings-heading[data-id="cosmic-theme-settings"] .setting-item-name {
  color: var(--text-normal);
  font-family: var(--font-interface-theme);
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  > .style-settings-collapse-indicator {
  color: var(--cosmic-accent);
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container {
  color: var(--text-normal);
  padding: 0 1.1rem 1rem;
  border: 1px solid var(--background-modifier-border);
  border-top: 3px solid
    color-mix(in srgb, var(--cosmic-accent) 72%, transparent);
  border-radius: 0 0 var(--radius-m) var(--radius-m);
  background-color: var(--background-primary-alt);
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  :is(.setting-item-name, .setting-item-description) {
  font-family: var(--font-interface-theme);
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item-name {
  color: var(--text-normal);
  font-weight: 600;
  letter-spacing: 0;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item[data-id="cosmic-info"] {
  margin: 0;
  padding: 0.85rem 0;
  border: 0;
  border-bottom: 1px solid var(--background-modifier-border);
  border-radius: 0;
  background: transparent;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item[data-id="cosmic-info"]
  .setting-item-name {
  color: var(--text-muted);
  font-family: var(--font-interface-theme);
  font-size: var(--font-ui-medium);
  font-weight: 600;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-heading[data-level="1"] {
  margin-top: 0.85rem;
  padding: 0.7rem 0 0.55rem;
  border: 0 !important;
  border-bottom: 1px solid var(--background-modifier-border) !important;
  border-radius: 0;
  background: transparent;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-heading[data-level="1"]
  .setting-item-name {
  color: var(--text-normal);
  font-family: var(--font-interface-theme);
  font-size: 1rem;
  font-weight: 700;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-heading[data-level="2"] {
  margin-top: 0.5rem;
  padding: 0.65rem 0 0.45rem;
  border: 0 !important;
  border-bottom: 1px solid
    color-mix(
      in srgb,
      var(--cosmic-accent) 24%,
      var(--background-modifier-border)
    ) !important;
  border-radius: 0;
  background: transparent;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-heading[data-level="2"]
  .setting-item-name {
  color: var(--text-muted);
  font-family: var(--font-interface-theme);
  font-weight: 650;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-heading
  + .style-settings-container {
  margin-bottom: 0.4rem;
  padding: 0 0.25rem;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-container
  > .setting-item:not(.style-settings-heading) {
  padding: 0.75rem 0;
  border-bottom-color: color-mix(
    in srgb,
    var(--background-modifier-border) 72%,
    transparent
  );
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-container
  > .setting-item:not(.style-settings-heading):hover {
  border-bottom-color: color-mix(
    in srgb,
    var(--cosmic-accent) 30%,
    var(--background-modifier-border)
  );
  background-color: transparent;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item-description {
  max-width: 46rem;
  color: var(--text-muted);
  font-weight: 400;
  line-height: 1.45;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  :is(.style-settings-heading, .setting-item[data-id="cosmic-info"])
  .setting-item-description:empty {
  display: none;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .style-settings-collapse-indicator {
  color: var(--cosmic-accent);
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item-control {
  gap: 0.45rem;
  color: var(--text-normal);
  font-family: var(--font-interface-theme);
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item-control
  :is(button, input, select, textarea, .dropdown) {
  color: var(--text-normal);
  font-family: inherit;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item-control
  :is(select, .dropdown) {
  min-width: 10rem;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item[data-id="cosmic-color-scheme"]
  :is(.setting-item-info, .setting-item-name, .setting-item-description) {
  text-align: start;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item[data-id="cosmic-color-scheme"]
  .setting-item-control {
  flex: 0 0 auto;
  justify-content: flex-start;
  margin-inline-start: auto;
  text-align: start;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .setting-item[data-id="cosmic-color-scheme"]
  :is(select, .dropdown) {
  min-width: 14rem;
  text-align: start;
  text-align-last: start;
}

.style-settings-heading[data-id="cosmic-theme-settings"]
  + .style-settings-container
  .pickr
  .pcr-button {
  border: 1px solid var(--cosmic-control-border);
  box-shadow: none;
}

/* Finishing details */

::selection {
  color: var(--text-normal);
  background: color-mix(in srgb, var(--cosmic-accent) 32%, transparent);
}

* {
  scrollbar-color: color-mix(in srgb, var(--cosmic-accent) 42%, transparent)
    transparent;
}

.workspace-leaf-resize-handle,
.workspace-split.mod-root .workspace-leaf-resize-handle {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 18%,
    var(--background-modifier-border)
  );
}

.nav-file-title,
.nav-folder-title,
.tree-item-self,
.setting-item {
  transition:
    color var(--cosmic-transition-duration) ease,
    background-color var(--cosmic-transition-duration) ease,
    border-color var(--cosmic-transition-duration) ease,
    box-shadow var(--cosmic-transition-duration) ease;
}

.nav-file-title:hover,
.nav-folder-title:hover,
.tree-item-self:hover {
  background-color: color-mix(in srgb, var(--cosmic-accent) 10%, transparent);
}

.setting-item {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 14%,
    var(--background-modifier-border)
  );
}

.setting-item:hover {
  border-color: color-mix(
    in srgb,
    var(--cosmic-accent) 28%,
    var(--background-modifier-border)
  );
}

body.cosmic-reduce-effects {
  --cosmic-pane-glow-dark: 0%;
  --cosmic-pane-highlight-dark: 0%;
  --cosmic-pane-glow-light: 0%;
  --cosmic-pane-highlight-light: 0%;
  --cosmic-atmosphere-note-opacity: 100%;
  --cosmic-note-surface-opacity: 100%;
  --cosmic-transition-duration: 0ms;
}

body.cosmic-reduce-effects .workspace,
body.cosmic-reduce-effects .workspace::before {
  background: var(--background-primary);
}

@media (prefers-reduced-motion: reduce) {
  body {
    --cosmic-transition-duration: 0ms;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

@media (width <= 700px) {
  .style-settings-heading[data-id="cosmic-theme-settings"] {
    padding: 1rem;
  }

  .style-settings-heading[data-id="cosmic-theme-settings"]
    + .style-settings-container {
    padding: 0.6rem;
  }

  .style-settings-heading[data-id="cosmic-theme-settings"]
    + .style-settings-container
    .setting-item {
    align-items: flex-start;
  }

  .style-settings-heading[data-id="cosmic-theme-settings"]
    + .style-settings-container
    .setting-item-control {
    width: 100%;
  }

  .markdown-rendered.cosmic-card-grid,
  .markdown-preview-view.cosmic-card-grid,
  :is(.markdown-preview-view, .markdown-rendered).cosmic-list-cards
    > :is(ul, ol),
  .cosmic-list-cards
    :is(.markdown-preview-view, .markdown-rendered)
    > :is(ul, ol),
  :is(.markdown-preview-view, .markdown-source-view).cosmic-properties-card
    .metadata-properties,
  .cosmic-properties-card
    :is(.markdown-preview-view, .markdown-source-view)
    .metadata-properties {
    grid-template-columns: 1fr;
  }

  .markdown-rendered table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  :is(.markdown-preview-view, .markdown-rendered).cosmic-wide-media
    :is(img, video, iframe, .internal-embed),
  .cosmic-wide-media
    :is(.markdown-preview-view, .markdown-rendered)
    :is(img, video, iframe, .internal-embed) {
    width: 100%;
    max-width: 100%;
    margin-inline: 0;
    transform: none;
  }
}

@media (forced-colors: active) {
  :is(button, input, select, textarea, a, .clickable-icon):focus-visible {
    outline: 2px solid Highlight;
  }

  .nav-file-title.is-active,
  .workspace-tab-header.is-active,
  .callout,
  .internal-embed,
  .markdown-rendered pre {
    border-color: Highlight;
  }
}

@media print {
  :root,
  body,
  body.theme-dark,
  body.theme-light {
    --background-primary: #fff;
    --background-primary-alt: #fff;
    --background-secondary: #fff;
    --background-secondary-alt: #fff;
    --text-normal: #17151c;
    --text-muted: #45414d;
    --text-faint: #67616f;

    color: #17151c;
    background: #fff !important;
  }

  .workspace,
  .workspace::before,
  .workspace-leaf,
  .workspace-leaf-content,
  .view-content,
  .markdown-reading-view,
  .markdown-preview-view,
  .markdown-rendered {
    color: #17151c !important;
    background: #fff !important;
    box-shadow: none !important;
  }

  .workspace-ribbon,
  .workspace-tab-header-container,
  .view-header,
  .status-bar,
  .sidebar-toggle-button,
  .mod-left-split,
  .mod-right-split,
  .copy-code-button,
  .metadata-add-button,
  .callout-fold,
  .embedded-backlinks,
  .markdown-preview-pusher {
    display: none !important;
  }

  .markdown-rendered {
    max-width: none !important;
    padding: 0 !important;
  }

  .markdown-rendered :is(h1, h2, h3, h5, h4, h6) {
    color: #17151c !important;
    text-shadow: none !important;
    break-after: avoid-page;
  }

  .markdown-rendered :is(h1, h2, h3, h5, h4, h6)::before,
  .markdown-rendered :is(h1, h2, h3, h5, h4, h6)::after {
    color: #55505c !important;
  }

  .markdown-rendered
    :is(
      pre,
      blockquote,
      table,
      img,
      figure,
      .callout,
      .internal-embed,
      .file-embed
    ) {
    break-inside: avoid-page;
    box-shadow: none !important;
  }

  .markdown-rendered :is(.callout, .internal-embed, .file-embed, pre, table) {
    border-color: #aaa4b0 !important;
    background: #fff !important;
  }

  .markdown-rendered a {
    color: #342a56 !important;
    text-decoration: underline;
  }

  .markdown-rendered table {
    display: table;
    width: 100%;
  }

  .markdown-rendered thead {
    display: table-header-group;
  }

  .markdown-rendered tr {
    break-inside: avoid-page;
  }
}
